import{FAUNA_DEF as g}from"../sim/fauna.js?v=0223731";import{enUnidades as f}from"../sim/comida.js?v=0223731";const c=(a,l)=>({es:a,en:l}),u=(a,l=a)=>({es:a,en:l}),o=(a,l,p,b,y)=>({id:`fauna/${a}`,seccion:"fauna",icono:l,contenido:p,datos:b,relacionadas:y}),t=Object.fromEntries([...g.especies.map(a=>[a.tipo,a]),["marabunta",{...g.marabunta,tipo:"marabunta",bocado:2e3,prob:0}]]),w=(a,l,p)=>u(`${String(a).replace(".",",")}${l}`,`${a}${p}`),e=a=>f(t[a].carne),m=a=>Math.ceil(t[a].carne/(t[a].bocado||2e3)),n=a=>{const l=m(a),p=l===1?"":"s";return{etiqueta:c("Carne","Meat"),valor:w(e(a),` de comida \xB7 ${l} bocado${p}`,` food \xB7 ${l} bite${p}`)}},s=a=>({etiqueta:c("Vida","Life"),valor:u(`${t[a].vida} mordiscos`,`${t[a].vida} bites`)}),i=a=>({etiqueta:c("Paso","Pace"),valor:t[a].paso===1?u("1 casilla por turno","1 tile per turn"):u(`1 casilla cada ${t[a].paso} turnos`,`1 tile every ${t[a].paso} turns`)}),h=a=>({etiqueta:c("Peso del brote","Spawn weight"),valor:t[a].prob?u(`${Math.round(t[a].prob*100)} % de los brotes`,`${Math.round(t[a].prob*100)} % of spawns`):u("No brota de d\xEDa","Never spawns by day")}),d=(a,l)=>({etiqueta:c("Coste medido","Measured cost"),valor:u(a,l)}),r=(a,l)=>({etiqueta:c("Dieta","Diet"),valor:u(a,l)}),z=[o("pulgon","bicho",{es:{titulo:"El pulg\xF3n",subtitulo:"Comida gratis, pero poca",resumen:`Verde p\xE1lido, torpe y sin una sola defensa: ${e("pulgon")} de comida que se dejan cazar. Es el cuerpo m\xE1s peque\xF1o del campo, y desde que la carne sale del tama\xF1o es tambi\xE9n el que menos paga \u2014 pero no cuesta absolutamente nada, y con la despensa en las \xFAltimas ${e("pulgon")} gratis son ${e("pulgon")}.`,bloques:[{titulo:"Qu\xE9 es",texto:"PRESA: no muerde, no persigue y no toca tus migas. Solo se aparta, y despacio, cuando tiene una hormiga a cuatro casillas o menos. Cae con cuatro mordiscos, as\xED que una obrera sola lo tumba sin ayuda de nadie. Su cuerpo es mayor que el de una hormiga: no se le pisa, y se le muerde desde dos casillas."},{titulo:"C\xF3mo se caza",texto:"Con la orden de CAZAR, que es la que hace que una hormiga muerda de verdad: cruzarse con \xE9l por el camino ya no lo mata. Medido en el laboratorio de caza dirigida, con dos cazadoras cae en once turnos y con ocho en dos, y en veinticuatro cacer\xEDas no cost\xF3 ni una baja. Muere mucho antes de que la presa acorralada llegue a revolverse."},{titulo:"D\xF3nde sale",texto:"Uno de cada cinco brotes es un pulg\xF3n, el peso m\xE1s alto del cat\xE1logo junto con la oruga. Con estaciones asoma en primavera y verano, con el resto de los pac\xEDficos. Sale en todos los sitios, nunca a menos de diez casillas de un hormiguero, y al anochecer se retira sin dejar carcasa."}],consejo:`Es la m\xE1s barata del campo y la que menos llena: su carcasa son ${m("pulgon")} bocados, as\xED que una obrera sola se lo lleva entero en ${m("pulgon")} viajes. Entre dos piezas a la vista, ve a por la otra \u2014 el pulg\xF3n es lo que se caza de camino, no aquello por lo que se desv\xEDa una columna.`,palabras:["pulg\xF3n","presa","carne","gratis","bicho","caza"]},en:{titulo:"The aphid",subtitulo:"Free food, and not much of it",resumen:`Pale green, clumsy and utterly defenceless: ${e("pulgon")} units of food that let themselves be caught. It has the smallest body in the field and, now that meat follows size, it pays the least of anything \u2014 but it costs absolutely nothing, and with the pantry scraping bottom ${e("pulgon")} for free is ${e("pulgon")}.`,bloques:[{titulo:"What it is",texto:"PREY: it does not bite, does not chase and never touches your crumbs. It only edges away, slowly, once an ant is within four tiles. Four bites bring it down, so a lone worker can finish it unaided. Its body is bigger than an ant\u2019s: you cannot walk over it, and it is bitten from two tiles away."},{titulo:"Hunting it",texto:"Use the HUNT order, the one that makes an ant actually bite: walking into a creature no longer kills it. Measured in the directed-hunt lab, two hunters bring it down in four turns and eight in barely one, and across twenty-four hunts it never cost a single ant. It dies long before cornered prey gets to lash back."},{titulo:"Where it turns up",texto:"One in five spawns is an aphid, tied with the caterpillar for the heaviest weight in the catalogue. With seasons on it appears in spring and summer alongside the other harmless ones. It shows up at every location, never within ten tiles of an anthill, and at nightfall it withdraws leaving no carcass."}],consejo:`It is the cheapest thing in the field and the least filling: its carcass is ${m("pulgon")} bites, so one worker carries the lot home in ${m("pulgon")} trips. Given two targets in sight, go for the other one \u2014 the aphid is what you kill in passing, not what you divert a column for.`,palabras:["aphid","prey","meat","free","creature","hunt"]}},[r("Presa","Prey"),n("pulgon"),s("pulgon"),i("pulgon"),h("pulgon"),d("Ninguna hormiga","No ants")],["mundo/fauna","fauna/mariquita","hormiguero/despensa"]),o("escarabajo","bicho",{es:{titulo:"El escarabajo",subtitulo:`${e("escarabajo")} de carne y un coletazo`,resumen:"Marr\xF3n, ancho y duro: la presa grande del campo. No ataca a nadie, pero cobra su propio despiece en vida \u2014 quien lo muerde mucho rato acaba pagando una hormiga. Es la pieza de manada del cat\xE1logo.",bloques:[{titulo:"Qu\xE9 es",texto:"PRESA GRANDE: ni muerde ni come de tu campo, solo huye, y a una casilla cada tres turnos. Aguanta treinta y seis mordiscos, nueve veces lo que un pulg\xF3n, y tiene el segundo cuerpo m\xE1s ancho del cat\xE1logo. Es una de las piezas grandes que se pueden abatir de verdad, y con manada sale gratis."},{titulo:"C\xF3mo se caza",texto:"Con manada, y no hay atajo \u2014 pero la manada sale GRATIS. Su cuerpo aguanta trece hormigas agarradas a la vez, y el coletazo ya no ejecuta a una: reparte castigo de vigor entre todas las que lleva encima, as\xED que cuatro o m\xE1s lo absorben y ninguna cae. Medido: con dos cazadoras no cay\xF3 ninguno de seis intentos y cost\xF3 DOS hormigas; con cuatro cayeron los seis, en catorce turnos y sin una sola baja; con ocho, en seis turnos. Ir a por \xE9l con dos es tirar dos obreras; ir con cuatro es comida gratis."},{titulo:"D\xF3nde sale",texto:"Casi uno de cada cinco brotes. Es pac\xEDfico, as\xED que con estaciones asoma en primavera y verano. Sale en todos los sitios y, como todos los diurnos, se va al anochecer sin dejar carcasa: un escarabajo a medio matar cuando cae la luz es trabajo tirado."}],consejo:`${e("escarabajo")} de comida por ninguna hormiga es de los mejores cambios del campo\u2026 si vas con cuatro. Con dos es tirar dos obreras y no cae. Y no lo empieces de tarde: si anochece a medias, se lleva la carne con \xE9l.`,palabras:["escarabajo","presa grande","manada","coletazo","carne"]},en:{titulo:"The beetle",subtitulo:`${e("escarabajo")} of meat and one kick`,resumen:"Brown, broad and tough: the field\u2019s big prey. It attacks nobody, yet it charges for its own butchering while still alive \u2014 bite it long enough and it takes an ant with it. This is the pack target of the catalogue.",bloques:[{titulo:"What it is",texto:"LARGE PREY: it neither bites nor grazes on your food, it just flees, one tile every three turns. It takes thirty-six bites, nine times what an aphid takes, and carries the second widest body in the catalogue. It is one of the big targets that can really be brought down, and with a pack it comes free."},{titulo:"Hunting it",texto:"In a pack, with no shortcut. Measured: with two hunters none of six attempts went down and it still cost over one ant; with four, four of six fell in fifteen turns; with eight, all six fell in eleven turns for one ant. Twelve is no better than eight, because the kick lands on the fifth straight turn of biting \u2014 and every twenty after that \u2014 and a pack takes a while to close around it."},{titulo:"Where it turns up",texto:"Nearly one spawn in five. It is a harmless one, so with seasons on it shows in spring and summer. It appears at every location and, like every daytime creature, leaves at nightfall without a carcass: a half-killed beetle at dusk is wasted work."}],consejo:`${e("escarabajo")} of food for no ants at all is one of the best trades in the field\u2026 if you bring four. With two it is throwing away two workers and it still does not fall. And do not start late: caught by dusk halfway through, it takes the meat with it.`,palabras:["beetle","large prey","pack","kick","meat"]}},[r("Presa grande","Large prey"),n("escarabajo"),s("escarabajo"),i("escarabajo"),h("escarabajo"),d("Ninguna con 4 o m\xE1s; 2 hormigas con solo 2","None with 4+; 2 ants with only 2")],["mundo/fauna","fauna/oruga","fauna/saltamontes"]),o("oruga","bicho",{es:{titulo:"La oruga",subtitulo:"Se come tu campo y engorda con \xE9l",resumen:"Verde azulada, gorda y lenta. Es la HERB\xCDVORA de manual: busca migas hasta catorce casillas, se las traga y se suma a su propia carne buena parte de lo que val\xEDa cada una. Cazarla recupera algo de lo que te quit\xF3; dejarla vaciar el campo, no.",bloques:[{titulo:"Qu\xE9 es",texto:`HERB\xCDVORA: no muerde a nadie. Lo suyo es la comida del suelo \u2014 ve las migas desde catorce casillas y va derecha a por ellas. De salida da ${e("oruga")} de carne, lo mismo que un escarabajo, pero cada miga que se traga se le suma encima: una oruga que lleva rato comiendo vale bastante m\xE1s que una reci\xE9n brotada, y una hoja grande le engorda el doble que una semilla.`},{titulo:"C\xF3mo se caza",texto:"Aguanta treinta mordiscos y se revuelve igual que el escarabajo: reparte el castigo entre las agarradas en vez de llevarse a una. Medido: con dos cazadoras no cay\xF3 ninguna de seis y cost\xF3 dos hormigas; con cuatro cayeron las seis, en nueve turnos y sin bajas; con ocho, en cuatro. Con la manada montada cae antes que el escarabajo, sencillamente porque tiene menos vida."},{titulo:"D\xF3nde sale",texto:"Uno de cada cinco brotes, empatada con el pulg\xF3n en el peso m\xE1s alto del cat\xE1logo. Con estaciones sale con los pac\xEDficos, en primavera y verano. Aparece en todos los sitios y de noche se retira como los dem\xE1s, con lo que llevara comido dentro."}],consejo:`La cuenta cambia con lo que ya se haya zampado. ${e("oruga")} de carne por ninguna hormiga ya es buen negocio de salida; lo que la hace todav\xEDa mejor es que cada miga que no le quitas se la queda ella. C\xE1zala pronto, mientras a\xFAn est\xE1 lejos de tu campo de migas.`,palabras:["oruga","herb\xEDvora","migas","engorda","carne"]},en:{titulo:"The caterpillar",subtitulo:"It eats your field and grows on it",resumen:"Blue-green, fat and slow. The textbook HERBIVORE: it looks for crumbs up to fourteen tiles away, swallows them and adds a good share of each one to its own meat. Killing it claws back part of what it took; letting it strip the field does not.",bloques:[{titulo:"What it is",texto:`HERBIVORE: it bites nobody. Ground food is its business \u2014 it spots crumbs fourteen tiles off and heads straight for them. It starts at ${e("oruga")} of meat, the same as a beetle, but every crumb it swallows piles on top: a caterpillar that has been feeding is worth far more than a freshly spawned one, and a big leaf fattens it twice as much as a seed.`},{titulo:"Hunting it",texto:"It takes thirty bites and lashes back exactly like the beetle. Measured: with two hunters none of six fell; with four, five of six went down in fourteen turns; with eight, all six in nine turns for one ant. Once the pack is in place it drops faster than the beetle, simply because it has less life."},{titulo:"Where it turns up",texto:"One spawn in five, tied with the aphid for the heaviest weight in the catalogue. With seasons on it comes out with the harmless ones, in spring and summer. It appears everywhere and withdraws at night like the rest, carrying whatever it has eaten inside it."}],consejo:`The maths shift with whatever it has already swallowed. ${e("oruga")} of meat for no ants is already a good trade on its own; what makes it better still is that every crumb you fail to take is a crumb it keeps. Hunt it early, while it is still far from your crumb field.`,palabras:["caterpillar","herbivore","crumbs","fattens","meat"]}},[r("Herb\xEDvora","Herbivore"),n("oruga"),s("oruga"),i("oruga"),h("oruga"),d("Ninguna con 4 o m\xE1s; 2 hormigas con solo 2","None with 4+; 2 ants with only 2")],["mundo/fauna","fauna/saltamontes","fauna/escarabajo"]),o("avispa","bicho",{es:{titulo:"La avispa",subtitulo:"Vive en el aire y baja seis turnos de cada dieciocho",resumen:"Amarillo vivo, que es el color con el que un animal avisa de que pica. Es INSECT\xCDVORA: persigue a tus hormigas desde nueve casillas y mata con el abdomen. Y vive en el aire \u2014 mientras vuela, morderla no le hace absolutamente nada.",bloques:[{titulo:"Qu\xE9 es",texto:`Nace volando y solo baja a descansar: doce turnos en el aire y seis posada, una y otra vez. En el aire nadie la alcanza, igual que la reina en vuelo nupcial tampoco es blanco de nadie, pero ella s\xED pica desde arriba y se encara al rev\xE9s sobre su v\xEDctima para clavar el aguij\xF3n. Aguanta veintis\xE9is mordiscos y, con el cuerpo que tiene, deja ${e("avispa")} de carne: de las que mejor pagan del campo, si consigues cercarla.`},{titulo:"C\xF3mo se caza",texto:"RODE\xC1NDOLA POSADA. Perseguirla sigue siendo regalarle bajas \u2014en el aire no le haces nada\u2014, pero desde el 2026-09-02 levantar el vuelo tampoco es inmediato: toma impulso un par de turnos, y si en esos turnos tiene encima un corro de siete u ocho hormigas NO DESPEGA, pierde el impulso y se queda en tierra. Medido: con dos o con cuatro cazadoras no cay\xF3 ninguna de seis y cost\xF3 de dos a tres hormigas; con ocho en corro cayeron las seis, en cuatro turnos y por una hormiga. O la cercas de verdad, o no vas."},{titulo:"D\xF3nde sale",texto:"Ocho de cada cien brotes. Es de las que muerden, as\xED que con estaciones solo asoma en oto\xF1o e invierno, reparti\xE9ndose ese turno con la lib\xE9lula. Sale en todos los sitios y al anochecer se retira como el resto de los diurnos."}],consejo:`No la persigas: en el aire no le haces nada y detr\xE1s de ella solo se pierden obreras. Recoge a las que est\xE9n sueltas y aguanta. Ahora bien, muerta paga ${e("avispa")}: si la quieres, c\xF3gela posada y con la manada ya puesta, nunca corriendo detr\xE1s.`,palabras:["avispa","insect\xEDvora","aguij\xF3n","vuelo","amenaza"]},en:{titulo:"The wasp",subtitulo:"It lives airborne and lands six turns in every eighteen",resumen:"Bright yellow, the colour an animal wears to warn that it stings. It is INSECTIVOROUS: it chases your ants from nine tiles away and kills with its abdomen. And it lives in the air \u2014 while it flies, biting it does nothing whatsoever.",bloques:[{titulo:"What it is",texto:`It is born flying and only comes down to rest: twelve turns aloft, six perched, over and over. Nothing reaches it in the air, just as a queen on her nuptial flight is nobody\u2019s target, yet it stings from above, curling backwards over its victim to drive the sting home. It takes twenty-six bites and, with the body it has, leaves ${e("avispa")} of meat: one of the better payers in the field, if you can ring it in.`},{titulo:"Hunting it",texto:"By waiting for it to land, and even then not always. The moment it drops below half life with anyone on top of it, it takes off at once and never perches beside you again. Measured: twenty-four directed chases with two, four, eight and twelve hunters, not one wasp brought down, and between one and a half and four ants lost per attempt. Chasing it is handing it casualties."},{titulo:"Where it turns up",texto:"Eight spawns in a hundred. It is one of the biters, so with seasons on it only appears in autumn and winter, sharing that shift with the dragonfly. It shows up at every location and withdraws at nightfall like the rest of the daytime creatures."}],consejo:`Do not chase it: in the air you do nothing to it and all you lose behind it is workers. Gather up whoever is out in the open and hold. That said, dead it pays ${e("avispa")}: if you want it, catch it perched with the pack already in place, never at a run.`,palabras:["wasp","insectivore","sting","flight","threat"]}},[r("Insect\xEDvora voladora","Flying insectivore"),n("avispa"),s("avispa"),i("avispa"),h("avispa"),d("1 hormiga, rode\xE1ndola posada con 8","1 ant, surrounding it grounded with 8")],["mundo/fauna","fauna/libelula","caracteristicas/guerrera"]),o("saltamontes","bicho",{es:{titulo:"El saltamontes",subtitulo:`${e("saltamontes")} de carne, y brincan`,resumen:"Verde hierba, grande y DESCONFIADO. Es HERB\xCDVORO como la oruga \u2014busca migas a diez casillas\u2014, pero lo suyo no es andar: se impulsa. Es la \xFAnica pieza que nace con su propia talla, as\xED que dos saltamontes nunca son iguales, y la \xFAnica que te ve venir de lejos: se aparta antes de que ninguna hormiga lo tenga a tiro.",bloques:[{titulo:"Qu\xE9 es",texto:`De las piezas m\xE1s gordas del campo: ${e("saltamontes")} de carne y cuarenta y ocho mordiscos de aguante, que no sirven de nada si no lo alcanzas. Cada uno nace con un tama\xF1o propio, hasta un treinta por ciento arriba o abajo, y con \xE9l le crecen o le menguan a la vez la carne, la vida y el brinco: hay saltamontes que valen casi el doble que otros. El grande, adem\xE1s, se mueve menos a menudo \u2014 y por eso es al que se alcanza. Y ES DISTANTE, que es lo primero que hay que saber de \xE9l: las dem\xE1s presas se apartan con una hormiga a cuatro casillas y \xE9l a DIEZ, m\xE1s lejos de lo que ve ninguna hormiga, as\xED que se entera \xE9l antes de que lo vean. Mientras dura el susto se mueve al doble de a menudo, no se replantea el rumbo una vez agachado a tomar impulso, y le da al hormiguero ese mismo margen de diez casillas: ni pasea por tus laderas ni el brinco lo deja en tu puerta. Medido: una escuadra de ocho ech\xE1ndosele encima SIN orden de cazar pasaba el 70% de los turnos con \xE9l a tiro de mordisco, y ahora el 34%.`},{titulo:"C\xF3mo se caza",texto:"RODE\xC1NDOLO. Su brinco es enorme sobre el papel, sesenta casillas, pero para en roca o en casilla pisada: medido en partida, el brinco medio real es de siete casillas, y solo en campo abierto y huyendo se va de veintiocho a treinta y ocho de una vez. Y AHORA HAY QUE GANARLE EL IMPULSO: el brinco no es inmediato \u2014se agazapa un par de turnos antes de despegar\u2014 y si en esos turnos lleva encima un cuarto de su cuerpo en hormigas agarradas NO SALTA, pierde la carga y se queda recuperando. Ah\xED es donde se le mata. Con menos peso salta, pero corto: la longitud se parte entre uno m\xE1s las que lleva. Herido a media vida se le queda en dos. Medido en el laboratorio: con cuatro cazadoras en corro cayeron los seis, en veinti\xFAn turnos y sin una baja; con ocho, en nueve; con dos, ninguno y cost\xF3 dos hormigas."},{titulo:"D\xF3nde sale",texto:"Catorce de cada cien brotes, con los pac\xEDficos: primavera y verano, en todos los sitios. Y solo brinca hacia delante \u2014 girar le cuesta el turno entero, posado en el suelo, y ese turno es justo el que le compra al cazador."}],consejo:"No lo persigas de frente: c\xF3rtale el rumbo. Cada giro que le obligas a dar es un turno que se queda quieto, y el que llega a media vida ya no brinca m\xE1s de dos casillas.",palabras:["saltamontes","herb\xEDvora","salto","brinco","talla","tama\xF1o","recelo","distante"]},en:{titulo:"The grasshopper",subtitulo:`${e("saltamontes")} of meat, and it leaps`,resumen:"Grass green, big and slippery. A HERBIVORE like the caterpillar \u2014 it looks for crumbs ten tiles out \u2014 but walking is not its way: it launches itself. It is also the only creature in the catalogue born with a size of its own, so no two grasshoppers are alike.",bloques:[{titulo:"What it is",texto:`One of the fattest targets in the field: ${e("saltamontes")} of meat and forty-eight bites of endurance, none of which matters if you cannot reach it. Each one is born within thirty per cent either side of the standard size, and that size scales its meat, its life and its leap together: some grasshoppers are worth almost twice what others are. The big ones also move less often \u2014 which is why they are the ones you catch.`},{titulo:"Hunting it",texto:"Ambush it or bleed it. Its leap is huge on paper, sixty tiles, but it stops at rock or at an occupied tile: measured in play, the real average leap is seven tiles, and only in open ground while fleeing does it cover twenty-eight to thirty-eight in one go. Wounded past half life it is cut down to two, and from there it does not get away. Measured in the lab: eight hunters brought down five of six in twelve turns for a little over one ant; two hunters brought down none."},{titulo:"Where it turns up",texto:"Fourteen spawns in a hundred, with the harmless ones: spring and summer, at every location. And it only leaps forwards \u2014 turning costs it a whole turn sitting on the ground, and that turn is exactly what a hunter buys."}],consejo:"Do not chase it head on: cut across its heading. Every turn you force it to make is a turn it spends still, and once it is past half life it never leaps more than two tiles.",palabras:["grasshopper","herbivore","leap","jump","size"]}},[r("Herb\xEDvora","Herbivore"),n("saltamontes"),s("saltamontes"),i("saltamontes"),h("saltamontes"),d("Ninguna con 4 o m\xE1s; 2 hormigas con solo 2","None with 4+; 2 ants with only 2")],["mundo/fauna","fauna/oruga","fauna/escarabajo"]),o("mariquita","bicho",{es:{titulo:"La mariquita",subtitulo:"El bocado de propina",resumen:`Roja, diminuta y la m\xE1s lenta de todo el campo: una casilla cada seis turnos. Tres mordiscos y cae. ${e("mariquita")} de comida no es una fortuna, pero es lo m\xE1s barato que hay, porque no cuesta absolutamente nada \u2014 y es el doble de lo que da un pulg\xF3n.`,bloques:[{titulo:"Qu\xE9 es",texto:"PRESA, como el pulg\xF3n: no muerde, no persigue y no toca tus migas. Solo se aparta cuando ve una hormiga a cuatro casillas, y se aparta despac\xEDsimo. Es la pieza m\xE1s fr\xE1gil del cat\xE1logo con diferencia, un mordisco menos que el pulg\xF3n, y aun as\xED ocupa m\xE1s que una hormiga: no se le pasa por encima."},{titulo:"C\xF3mo se caza",texto:"Sola. Medido: con dos cazadoras cae en menos de cuatro turnos y con ocho en uno, y en veinticuatro cacer\xEDas no cost\xF3 ni una baja. Como el pulg\xF3n, muere mucho antes de que el timer de la presa acorralada llegue a armarse siquiera."},{titulo:"D\xF3nde sale",texto:`Catorce de cada cien brotes, con los pac\xEDficos, en todos los sitios y siempre lejos de los hormigueros. Su carcasa se despieza en ${m("mariquita")} bocados, as\xED que una sola obrera se la lleva entera a casa en ${m("mariquita")} viajes. Al anochecer se retira sin dejar nada.`}],consejo:`No desv\xEDes una columna por ella, pero no la dejes pasar si la tienes al lado: ${e("mariquita")} de comida por nada siguen siendo ${e("mariquita")} de comida. Y como cada obrera solo carga un bocado por viaje, mejor dos que una.`,palabras:["mariquita","presa","gratis","carne","bicho"]},en:{titulo:"The ladybird",subtitulo:"The bonus mouthful",resumen:`Red, tiny and the slowest thing in the field: one tile every six turns. Three bites and it drops. ${e("mariquita")} of food is no fortune, but it is the cheapest food there is, because it costs absolutely nothing \u2014 and it is twice what an aphid gives.`,bloques:[{titulo:"What it is",texto:"PREY, like the aphid: it does not bite, does not chase and never touches your crumbs. It only shuffles aside when an ant comes within four tiles, and it shuffles very slowly indeed. It is by far the frailest thing in the catalogue, one bite under the aphid, and even so it takes up more room than an ant: you cannot step over it."},{titulo:"Hunting it",texto:"On your own. Measured: two hunters drop it in three turns and eight in barely one, and across twenty-four hunts it never cost a casualty. Like the aphid, it dies long before the cornered-prey timer even gets a chance to arm itself."},{titulo:"Where it turns up",texto:`Fourteen spawns in a hundred, with the harmless ones, at every location and always well clear of the anthills. Its carcass splits into ${m("mariquita")} bites, so a single worker can carry the whole thing home in ${m("mariquita")} trips. At nightfall it withdraws leaving nothing behind.`}],consejo:`Do not divert a column for it, but do not let it walk by either: ${e("mariquita")} of food for nothing is still ${e("mariquita")} of food. And since each worker only carries one bite per trip, two beat one.`,palabras:["ladybird","ladybug","prey","free","meat"]}},[r("Presa","Prey"),n("mariquita"),s("mariquita"),i("mariquita"),h("mariquita"),d("Ninguna hormiga","No ants")],["mundo/fauna","fauna/pulgon","hormiguero/despensa"]),o("libelula","bicho",{es:{titulo:"La lib\xE9lula",subtitulo:"Te ve desde diez casillas y llega la primera",resumen:"Cian azulado, larga y r\xE1pida: la cazadora m\xE1s veloz a plena luz, una casilla cada dos turnos. Persigue desde m\xE1s lejos que nadie y mata con las patas, sin aguij\xF3n. A cambio es la que menos aguanta de las que muerden \u2014 y, por ser el bicho m\xE1s grande que hay, la que M\xC1S carne deja de todo el cat\xE1logo.",bloques:[{titulo:"Qu\xE9 es",texto:`INSECT\xCDVORA que vive en el aire igual que la avispa, pero con otro reparto: diecis\xE9is turnos volando y solo cuatro posada. Aguanta dieciocho mordiscos, lo m\xE1s blando que muerde en todo el cat\xE1logo, y deja ${e("libelula")} de carne: es el cuerpo m\xE1s grande del campo y la pieza que m\xE1s paga con diferencia. Cazarla es defenderse Y llenar la despensa, si consigues cercarla posada.`},{titulo:"C\xF3mo se caza",texto:"Igual que la avispa: en el aire no le haces nada, y por debajo de media vida con hormigas encima ya no se posa. Lo que s\xED se puede es NO DEJARLA DESPEGAR \u2014 el impulso le cuesta un par de turnos y un corro se lo quita. Medido: con dos o con cuatro cazadoras no cay\xF3 ninguna de seis; con ocho en corro cayeron las seis, en TRES turnos y por una hormiga (es la pieza m\xE1s blanda del cat\xE1logo). Su ventana en tierra es a\xFAn m\xE1s corta que la de la avispa, as\xED que hay que estar ya puestas."},{titulo:"D\xF3nde sale",texto:"Seis de cada cien brotes, el peso m\xE1s bajo de todo lo que brota de d\xEDa \u2014 se lo cedi\xF3 la avispa, de modo que la presi\xF3n voladora total es la de siempre, solo que repartida entre dos bichos. Con estaciones, oto\xF1o e invierno, y en todos los sitios."}],consejo:`Mata poco a menudo: su recarga es la m\xE1s larga de las que muerden, y lo que hace da\xF1o es que te alcanza. Recoge a las sueltas antes que nada\u2026 y luego m\xF3ntale el corro donde se pose: ${e("libelula")} por una hormiga es la mejor pieza del campo.`,palabras:["lib\xE9lula","insect\xEDvora","vuelo","veloz","amenaza"]},en:{titulo:"The dragonfly",subtitulo:"It spots you ten tiles off and gets there first",resumen:"Blue-cyan, long and quick: the fastest hunter in broad daylight, one tile every two turns. It chases from further out than anything else and kills with its legs, with no sting. In exchange it is the most fragile of the biters and, being the largest creature there is, the one that leaves the most meat in the whole catalogue.",bloques:[{titulo:"What it is",texto:`An INSECTIVORE that lives airborne like the wasp, but on a different split: sixteen turns flying and only four perched. It takes eighteen bites, the softest of anything that bites in the catalogue, and leaves ${e("libelula")} of meat: it has the largest body in the field and pays more than anything else by a distance. Killing it is self-defence AND stocking the pantry, if you can ring it in while it is perched.`},{titulo:"Hunting it",texto:"Like the wasp, with the same bad news: in the air you do nothing to it, and below half life with ants on top of it, it stops perching. Measured: twenty-four directed chases, not one dragonfly brought down, between one and a half and four and a half ants lost. Its window on the ground is even shorter than the wasp\u2019s."},{titulo:"Where it turns up",texto:"Six spawns in a hundred, the lightest weight of anything that spawns by day \u2014 the wasp gave up that share, so the total flying pressure is what it always was, only split between two creatures. With seasons on, autumn and winter, at every location."}],consejo:`It kills rarely: its reload is the longest of the biters, and what hurts is that it reaches you at all. Gather in the stragglers before anything else\u2026 then ring it where it lands: ${e("libelula")} for one ant is the best prize in the field.`,palabras:["dragonfly","insectivore","flight","fast","threat"]}},[r("Insect\xEDvora voladora","Flying insectivore"),n("libelula"),s("libelula"),i("libelula"),h("libelula"),d("1 hormiga, rode\xE1ndola posada con 8","1 ant, surrounding it grounded with 8")],["mundo/fauna","fauna/avispa","mundo/clima"]),o("arana","bicho",{es:{titulo:"La ara\xF1a",subtitulo:"Se lleva una hormiga y se va",resumen:"Gris morado casi negro, y solo de noche. No brota nunca de d\xEDa: la trae el evento nocturno, y asoma a seis casillas de la hormiga m\xE1s expuesta de cada colonia. Va a una casilla por turno, que de noche es m\xE1s de lo que anda una hormiga entumecida, y su presupuesto es exactamente una hormiga.",bloques:[{titulo:"Qu\xE9 es",texto:"NOCTURNA: sale cuando el campo ya se ha vaciado de los dem\xE1s bichos y se retira al amanecer sin dejar carcasa. Persigue desde nueve casillas y caza porque de noche tus hormigas son m\xE1s lentas que ella: el letargo elige a las v\xEDctimas. En cuanto alcanza a una se la lleva y desaparece \u2014 es un turno de caza, no una pelea. Es la MISMA ara\xF1a que la errante, con su mismo cuerpo: lo que las separa a la vista es que esta va oscura y es bastante m\xE1s peque\xF1a."},{titulo:"Qu\xE9 cuesta",texto:"Una hormiga, y no hay manada que lo evite. Medido en el laboratorio: veinticuatro noches con dos, cuatro, ocho y doce cazadoras rode\xE1ndola, y las veinticuatro veces se cobr\xF3 exactamente una hormiga y se fue sin dejar carne. Aguanta cuarenta mordiscos, as\xED que quitarle la pieza exigir\xEDa arranc\xE1rselos todos en el mismo turno en que te alcanza."},{titulo:"D\xF3nde sale",texto:"En todos los sitios: es la amenaza de noche que no falta en ninguno, del fiordo a la sabana. No puede haber m\xE1s ara\xF1as vivas a la vez que colonias tenga la partida, y el reloj repone las que caigan. Con Amenazas: Ninguna en el di\xE1logo de partida no sale ninguna. A la hormiga que anda por el aire de noche no la caza esta: a esa se la llevan sin que nadie la vea."}],consejo:"El contrajuego es no tener a nadie fuera. Quien elige la v\xEDctima es la distancia a tu hormiguero m\xE1s cercano, as\xED que paga la que duerme lejos de casa: guarece o acerca las columnas antes de que caiga la luz.",palabras:["ara\xF1a","nocturna","noche","amenaza","letargo"]},en:{titulo:"The spider",subtitulo:"It takes one ant and leaves",resumen:"A near-black muted purple-grey, and only after dark. It never spawns by day: the night event brings it, surfacing six tiles from the most exposed ant of each colony. It moves a tile every turn, which after dark is more than a numbed ant manages, and its budget is exactly one ant.",bloques:[{titulo:"What it is",texto:"NOCTURNAL: it comes out once the field has emptied of every other creature and withdraws at dawn leaving no carcass. It chases from nine tiles and hunts because at night your ants are slower than it is \u2014 torpor picks the victims. The instant it reaches one it carries her off and vanishes: this is a hunting shift, not a fight. It is the SAME spider as the wandering one, sharing its body: what tells them apart on sight is that this one is dark and a good deal smaller."},{titulo:"What it costs",texto:"One ant, and no pack prevents it. Measured in the lab: twenty-four nights with two, four, eight and twelve hunters ringed around it, and all twenty-four times it collected exactly one ant and left without meat. It takes forty bites, so stealing its prize would mean landing every one of them on the same turn it reaches you."},{titulo:"Where it turns up",texto:"Everywhere: it is the night threat no location goes without, from the fjord to the savanna. There can never be more spiders alive at once than the match has colonies, and the clock replaces any that fall. With Threats: None in the match dialog, none appear at all. An ant caught airborne at night is not this creature\u2019s doing: that one is taken without anyone seeing it."}],consejo:"The counterplay is having nobody outside. What picks the victim is distance from your nearest anthill, so the one sleeping far from home pays: shelter your columns or pull them in before the light goes.",palabras:["spider","nocturnal","night","threat","torpor"]}},[r("Cazadora nocturna","Nocturnal hunter"),n("arana"),s("arana"),i("arana"),h("arana"),d("1 hormiga, siempre","1 ant, always")],["mundo/noche","fauna/arana-errante","mundo/fauna"]),o("arana-errante","bicho",{es:{titulo:"La ara\xF1a errante",subtitulo:"La noche de los sitios c\xE1lidos",resumen:"Parda, grande y de acecho: la otra amenaza de la noche, y justo la contraria de la primera. Es la pieza m\xE1s dura de todo el cat\xE1logo y la del cuerpo m\xE1s ancho, pero anda a la mitad de velocidad. Solo asoma donde hace calor.",bloques:[{titulo:"Qu\xE9 es",texto:"NOCTURNA como la otra ara\xF1a, con el mismo cuerpo y con el mismo trato: se lleva una hormiga y se retira sin dejar carcasa. En el campo se la reconoce porque va parda y ocupa vez y media el ancho de la oscura. Lo que cambia es el car\xE1cter. Acecha en vez de correr \u2014una casilla cada dos turnos\u2014 y persigue desde siete casillas en lugar de nueve, as\xED que se la ve venir con m\xE1s margen. A cambio, cincuenta y seis mordiscos no se los arranca nadie de un turno."},{titulo:"Qu\xE9 cuesta",texto:`Lo mismo que la otra: una hormiga por noche y por colonia. Medido en el laboratorio, veinticuatro noches con dos, cuatro, ocho y doce cazadoras alrededor, y las veinticuatro se cobraron su pieza y se fueron sin dejar carne. Sus ${e("arana-errante")} de carne son de lo mejor del campo, pero para cobrarlas habr\xEDa que tumbarla en el turno mismo en que llega.`},{titulo:"D\xF3nde sale",texto:"Solo en los sitios c\xE1lidos: el oasis, el Amazonas, la sabana, el monz\xF3n y el outback. En el Mediterr\xE1neo, el fiordo, la taiga, la cumbre y la pradera no asoma: all\xED la noche es siempre la ara\xF1a de siempre. Cu\xE1l de las dos sale se echa a suertes cada noche entre las del sitio."}],consejo:"Elegir un sitio c\xE1lido es elegir esta noche. En el Amazonas o en la sabana cuenta con que la mitad de las noches la amenaza es la grande \u2014 y con que el contrajuego no cambia: nadie fuera.",palabras:["ara\xF1a errante","nocturna","tropical","sabana","amazonas","oasis"]},en:{titulo:"The wandering spider",subtitulo:"The night of the warm places",resumen:"Brown, big and stalking: the other threat of the night, and the exact opposite of the first. It is the toughest thing in the whole catalogue and the widest bodied, yet it walks at half the speed. It only shows up where the weather is warm.",bloques:[{titulo:"What it is",texto:"NOCTURNAL like the other spider, with the same body and on the same terms: it takes one ant and withdraws leaving no carcass. In the field you know it because it is brown and half again as wide as the dark one. What differs is the temperament. It stalks rather than runs \u2014 one tile every two turns \u2014 and chases from seven tiles instead of nine, so you see it coming with more room to spare. In return, nobody strips fifty-six bites off it in a single turn."},{titulo:"What it costs",texto:`The same as the other: one ant per night and per colony. Measured in the lab, twenty-four nights with two, four, eight and twelve hunters around it, and all twenty-four collected their prize and left without meat. Its ${e("arana-errante")} of meat are among the best in the field, but collecting them would mean felling it on the very turn it arrives.`},{titulo:"Where it turns up",texto:"Only in warm places: the oasis, the Amazon, the savanna, the monsoon and the outback. In the Mediterranean, the fjord, the taiga, the summit and the prairie it never appears: there the night is always the older spider. Which of the two comes out is drawn each night among those the location allows."}],consejo:"Choosing a warm location is choosing this night. In the Amazon or the savanna, expect half your nights to bring the big one \u2014 and expect the counterplay to be unchanged: nobody outside.",palabras:["wandering spider","nocturnal","tropical","savanna","amazon","oasis"]}},[r("Cazadora nocturna","Nocturnal hunter"),n("arana-errante"),s("arana-errante"),i("arana-errante"),h("arana-errante"),d("1 hormiga, siempre","1 ant, always")],["mundo/noche","fauna/arana","mundo/sitio"]),o("abeja","bicho",{es:{titulo:"La abeja",subtitulo:"Va a lo suyo: a las flores",resumen:`Amarillo miel, y la \xFAnica pieza del campo que no tiene nada que ver contigo. No muerde, no persigue y no toca tus migas: vuela de mancha en mancha de flora y se posa sobre ella. ${e("abeja")} de comida para quien sepa esperar a que baje.`,bloques:[{titulo:"Qu\xE9 es",texto:`POLINIZADORA: no ataca a nadie y no come del suelo, as\xED que ni te quita comida ni te cuesta hormigas. Vive en el aire como la avispa y la lib\xE9lula, pero con el reparto al rev\xE9s que ellas \u2014 ocho turnos volando y diez posada\u2014, y cuando baja lo hace sobre las flores, que es a donde va siempre que no la est\xE9n molestando. Aguanta diez mordiscos y deja ${e("abeja")} de comida, que para lo poco que cuesta es de lo mejor que hay.`},{titulo:"C\xF3mo se caza",texto:"Esper\xE1ndola en la flor. En el aire no le haces nada, igual que a las otras dos voladoras; la diferencia es que esta pasa m\xE1s tiempo abajo que arriba, y ah\xED s\xED. Con diez de vida, dos o tres obreras la tumban dentro de su descanso. Si una hormiga se le acerca a cuatro casillas se aparta \u2014es una presa, y como toda presa huye\u2014, as\xED que lo que funciona es tenerlas ya puestas donde va a posarse."},{titulo:"D\xF3nde sale",texto:"Seis de cada cien brotes, el peso que le cedi\xF3 la mariquita. Es DIURNA: al anochecer se retira con el resto y nunca aparece de noche. Con estaciones sale en primavera y verano, con los pac\xEDficos. En los mapas sin flora \u2014el oasis, donde la comida sale de las fuentes\u2014 no tiene flores a las que ir y pasea sin rumbo."}],consejo:`Es la pieza m\xE1s previsible del cat\xE1logo: sabes d\xF3nde va a estar. Si hay una abeja rondando, la flor m\xE1s cercana a tu hormiguero es una despensa de ${e("abeja")} que se repone sola \u2014 y no hace falta perseguir nada.`,palabras:["abeja","polinizadora","flores","flora","vuelo","presa"]},en:{titulo:"The bee",subtitulo:"It minds its own business: the flowers",resumen:`Honey yellow, and the only creature in the field with nothing to do with you. It does not bite, does not chase and does not touch your crumbs: it flies from one patch of flora to the next and perches on it. ${e("abeja")} of food for whoever can wait for it to come down.`,bloques:[{titulo:"What it is",texto:`A POLLINATOR: it attacks nobody and eats nothing off the ground, so it neither takes your food nor costs you ants. It lives airborne like the wasp and the dragonfly, but on the opposite split \u2014 eight turns flying and ten perched \u2014 and when it comes down it does so on the flowers, which is where it heads whenever nothing is bothering it. It takes ten bites and leaves ${e("abeja")} of food, which for what it costs is as good as it gets.`},{titulo:"Hunting it",texto:"By waiting at the flower. In the air you do nothing to it, same as the other two fliers; the difference is that this one spends more time down than up, and down it can be had. With ten of life, two or three workers fell it inside its rest. If an ant comes within four tiles it moves away \u2014 it is prey, and prey flees \u2014 so what works is having them already standing where it is going to land."},{titulo:"Where it turns up",texto:"Six spawns in a hundred, the share the ladybird gave up. It is DIURNAL: at dusk it withdraws with the rest and it never appears at night. With seasons on it comes out in spring and summer, with the peaceful ones. On maps with no flora \u2014 the oasis, where food comes from springs \u2014 it has no flowers to go to and drifts at random."}],consejo:`It is the most predictable piece in the catalogue: you know where it will be. If a bee is about, the flower nearest your anthill is a ${e("abeja")}-point pantry that restocks itself \u2014 and nothing has to be chased.`,palabras:["bee","pollinator","flowers","flora","flight","prey"]}},[r("Polinizadora voladora","Flying pollinator"),n("abeja"),s("abeja"),i("abeja"),h("abeja"),d("Se espera en la flor, no se persigue","Waited for at the flower, not chased")],["mundo/fauna","fauna/avispa","fauna/mariquita"]),o("escorpion","bicho",{es:{titulo:"El escorpi\xF3n",subtitulo:"La noche de los sitios secos",resumen:`Ocre y con aguij\xF3n: la amenaza nocturna del calor seco. Es la ara\xF1a errante del desierto \u2014grande, lenta y de acecho\u2014 pero pica con la cola. Es de las piezas m\xE1s duras del campo y deja ${e("escorpion")} de carne si la noche te sale a cuenta.`,bloques:[{titulo:"Qu\xE9 es",texto:"INSECT\xCDVORA NOCTURNA: no brota de d\xEDa. La trae el evento de la noche en los sitios secos y c\xE1lidos \u2014mediterr\xE1neo, dehesa, oasis, sabana, monz\xF3n, outback\u2014 en lugar de la ara\xF1a errante, y all\xED caza porque tus hormigas entumecidas por el letargo son m\xE1s lentas que ella. Persigue desde seis casillas y clava el aguij\xF3n como la avispa."},{titulo:"C\xF3mo se pelea",texto:`Como toda amenaza nocturna, su presupuesto es una hormiga: se lleva a la m\xE1s expuesta y se retira al amanecer. Es lenta (una casilla cada dos turnos), as\xED que da tiempo a rodearla, pero aguanta ${t.escorpion.vida} mordiscos: plantarle cara de noche, con la colonia media dormida, cuesta de verdad.`},{titulo:"D\xF3nde sale",texto:"Solo de noche y solo donde el sitio lo lista (0026 \xA74.3). En los desiertos ocupa el puesto que antes era del sol\xEDfugo o del huntsman; siempre queda una ara\xF1a de siempre de respaldo por si la noche no le toca a \xE9l."}],consejo:"De noche, recoge lo que puedas dentro y no salgas a buscarla: pagar\xE1s una hormiga la lleves como la lleves. De d\xEDa no existe: el campo seco es de la mantis y la termita.",palabras:["escorpi\xF3n","nocturna","aguij\xF3n","desierto","amenaza"]},en:{titulo:"The scorpion",subtitulo:"The night of the dry places",resumen:`Ochre and stinging: the nocturnal threat of dry heat. It is the desert\u2019s wandering spider \u2014 large, slow and ambushing \u2014 but it strikes with its tail. It is among the toughest things in the field and leaves ${e("escorpion")} of meat if the night pays off.`,bloques:[{titulo:"What it is",texto:"NOCTURNAL INSECTIVORE: it never spawns by day. The night event brings it to the dry, warm locations \u2014 Mediterranean, dehesa, oasis, savanna, monsoon, outback \u2014 in place of the wandering spider, and there it hunts because your torpid ants are slower than it is. It chases from six tiles and drives its sting home like the wasp."},{titulo:"Fighting it",texto:"Like every night threat its budget is one ant: it takes the most exposed and withdraws at dawn. It is slow (one tile every two turns), so there is time to ring it, but it is tough: standing up to it after dark, with the colony half asleep, genuinely costs."},{titulo:"Where it turns up",texto:"Only at night and only where the location lists it (0026 \xA74.3). In the deserts it takes the slot that used to be the solifuge\u2019s or the huntsman\u2019s; there is always an ordinary spider in reserve for the nights it is not drawn."}],consejo:"At night, bring in what you can and do not go looking for it: you will pay one ant however you take it. By day it does not exist \u2014 the dry field belongs to the mantis and the termite.",palabras:["scorpion","nocturnal","sting","desert","threat"]}},[r("Insect\xEDvora nocturna","Nocturnal insectivore"),n("escorpion"),s("escorpion"),i("escorpion"),h("escorpion"),d("Una hormiga por noche","One ant per night")],["fauna/arana-errante","fauna/escolopendra","mundo/fauna"]),o("mantis","bicho",{es:{titulo:"La mantis",subtitulo:"La primera cazadora de suelo que sale de d\xEDa",resumen:`Verde y quieta hasta que no lo est\xE1: la \xFAnica cazadora que persigue a tus hormigas a plena luz sin volar. Hasta ella, toda amenaza diurna volaba (avispa, lib\xE9lula) o esperaba a la noche (ara\xF1as). Aguanta ${t.mantis.vida} mordiscos y deja ${e("mantis")} de carne.`,bloques:[{titulo:"Qu\xE9 es",texto:"INSECT\xCDVORA DE D\xCDA: acecha como las ara\xF1as \u2014persigue desde cinco casillas y muerde\u2014 pero brota por la ruleta del d\xEDa como una presa cualquiera. No vuela: se la puede rodear y morder en el suelo, cosa que con la avispa y la lib\xE9lula no se puede."},{titulo:"C\xF3mo se caza",texto:"Con manada y con la orden de CAZAR o de ATACAR, como a todo lo que muerde. No se lleva a la primera que la toca: reparte su castigo entre las agarradas, as\xED que un corro aguanta lo que una sola no. Es la cazadora que s\xED se puede abatir de d\xEDa sin perseguir un punto por el aire."},{titulo:"D\xF3nde sale",texto:"Solo en los sitios que la listan (0026 \xA74.3): los secos y c\xE1lidos abiertos \u2014mediterr\xE1neo, oasis, sabana, caribe, pradera, monz\xF3n, outback, dehesa\u2014, nunca en los bosques cerrados ni en los tres fr\xEDos. Como todo lo diurno, al anochecer se retira sin dejar carcasa."}],consejo:"Tr\xE1tala como una avispa que no puede despegar: la misma amenaza, pero sin la parte imposible. C\xE9rcala en el suelo y cae; ign\xF3rala y te va mordiendo obreras sueltas.",palabras:["mantis","insect\xEDvora","cazadora","d\xEDa","suelo"]},en:{titulo:"The mantis",subtitulo:"The first ground hunter that comes out by day",resumen:`Green and still until it is not: the only hunter that chases your ants in broad daylight without flying. Until it arrived, every daytime threat either flew (wasp, dragonfly) or waited for night (spiders). It takes thirty bites and leaves ${e("mantis")} of meat.`,bloques:[{titulo:"What it is",texto:"DAYTIME INSECTIVORE: it ambushes like the spiders \u2014 chasing from five tiles and biting \u2014 yet spawns from the daytime roulette like any prey. It does not fly: it can be ringed and bitten on the ground, which the wasp and the dragonfly never allow."},{titulo:"Hunting it",texto:"With a pack and the HUNT or ATTACK order, as with everything that bites. It does not carry off the first ant to touch it: it spreads its punishment across those clamped on, so a ring endures what a lone worker cannot. It is the hunter you can actually bring down by day without chasing a dot through the air."},{titulo:"Where it turns up",texto:"Only where the location lists it (0026 \xA74.3): the open dry, warm places \u2014 Mediterranean, oasis, savanna, Caribbean, prairie, monsoon, outback, dehesa \u2014 never in the closed forests or the three cold sites. Like everything diurnal, it withdraws at nightfall leaving no carcass."}],consejo:"Treat it as a wasp that cannot take off: the same threat, minus the impossible part. Ring it on the ground and it falls; ignore it and it picks off loose workers.",palabras:["mantis","insectivore","hunter","daytime","ground"]}},[r("Insect\xEDvora de suelo","Ground insectivore"),n("mantis"),s("mantis"),i("mantis"),{etiqueta:c("Caza","Hunts from"),valor:u("Desde 5 casillas","From 5 tiles")},{etiqueta:c("D\xF3nde sale","Where it spawns"),valor:u("Solo en ciertos sitios (0026)","Only at certain locations (0026)")}],["fauna/avispa","fauna/libelula","mundo/fauna"]),o("termita","bicho",{es:{titulo:"La termita",subtitulo:"El ganado de los sitios c\xE1lidos",resumen:`P\xE1lida y menuda: la presa mansa donde el pulg\xF3n no pinta nada. Tan peque\xF1a como \xE9l \u2014cae con ${t.termita.vida} mordiscos\u2014 y deja ${e("termita")} de carne. Poca cosa una a una, pero brota en tanda y llena el campo c\xE1lido de comida f\xE1cil.`,bloques:[{titulo:"Qu\xE9 es",texto:"PRESA: no muerde, no persigue y no toca tus migas. Solo se aparta cuando tiene una hormiga cerca, y despacio. Cae con una obrera sola. Es el reemplazo del pulg\xF3n en los sitios donde el pulg\xF3n no vive."},{titulo:"C\xF3mo se caza",texto:"Con la orden de CAZAR; cruzarse con ella no la mata. Se abate sin ayuda y sin coste. Como el pulg\xF3n, es lo que se caza de camino, no aquello por lo que se desv\xEDa una columna."},{titulo:"D\xF3nde sale",texto:"Solo en los c\xE1lidos que la listan (0026 \xA74.3): oasis, sabana, amazonas, caribe, monz\xF3n, outback, con el peso m\xE1s alto de sus cat\xE1logos \u2014ocupa el hueco que el pulg\xF3n deja a cero\u2014. Diurna: al anochecer se retira sin dejar carcasa."}],consejo:"Es comida de relleno: gratis, pero poca. En un sitio c\xE1lido es lo que mantiene la despensa entre presas grandes, as\xED que no la desprecies cuando anda cerca de casa.",palabras:["termita","presa","ganado","c\xE1lido","carne"]},en:{titulo:"The termite",subtitulo:"The livestock of the warm places",resumen:`Pale and tiny: the meek prey where the aphid has no place. As small as the aphid \u2014 it drops in five bites \u2014 and leaves ${e("termita")} of meat. Little on its own, but it spawns in a batch and fills the warm field with easy food.`,bloques:[{titulo:"What it is",texto:"PREY: it does not bite, does not chase and never touches your crumbs. It only edges away, slowly, when an ant is near. A lone worker finishes it. It is the aphid\u2019s stand-in in the places the aphid does not live."},{titulo:"Hunting it",texto:"Use the HUNT order; walking into it does not kill it. It goes down unaided and for nothing. Like the aphid, it is what you kill in passing, not what you divert a column for."},{titulo:"Where it turns up",texto:"Only in the warm places that list it (0026 \xA74.3): oasis, savanna, Amazon, Caribbean, monsoon, outback, at the heaviest weight in their catalogues \u2014 it fills the slot the aphid is set to zero. Diurnal: it withdraws at nightfall leaving no carcass."}],consejo:"It is filler food: free, but scant. In a warm location it is what keeps the pantry ticking between big prey, so do not scorn it when it is near home.",palabras:["termite","prey","livestock","warm","meat"]}},[r("Presa","Prey"),n("termita"),s("termita"),i("termita"),{etiqueta:c("D\xF3nde sale","Where it spawns"),valor:u("Solo en sitios c\xE1lidos (0026)","Only at warm locations (0026)")},d("Ninguna hormiga","No ants")],["fauna/pulgon","fauna/mariquita","mundo/fauna"]),o("cigarra","bicho",{es:{titulo:"La cigarra",subtitulo:"Presa grande que vuela y se posa",resumen:`Parda y grande: la lib\xE9lula de las presas. Vive en el aire como la abeja, pero sin polinizar y sin morder \u2014 solo vuela y se posa en los \xE1rboles. Es la presa m\xE1s grande del campo y deja ${e("cigarra")} de carne cuando por fin baja.`,bloques:[{titulo:"Qu\xE9 es",texto:"PRESA VOLADORA: no ataca a nadie ni toca tus migas. Pasa mucho m\xE1s tiempo posada que volando (catorce turnos posada por cada seis en el aire), y en el aire nadie la muerde. Cae con pocos mordiscos una vez en tierra: su vida es corta para lo que abulta."},{titulo:"C\xF3mo se caza",texto:"Esperando a que se pose. Perseguirla en el aire no le hace nada, igual que a la abeja o a la avispa; pero pasa tanto rato en tierra que basta con tener la manada cerca de donde baja. Muerta paga mucho: es carne alta por poca vida."},{titulo:"D\xF3nde sale",texto:"Solo donde el sitio la lista (0026 \xA74.3): mediterr\xE1neo, dehesa, sabana, monz\xF3n, outback, caribe, amazonas, pradera. Diurna y sin dientes: con estaciones cae en el turno de los pac\xEDficos y al anochecer se retira sin carcasa."}],consejo:"Es el premio de las presas: mucha carne por poca vida. No corras tras ella; ten la manada donde suela posarse y c\xF3gela en tierra.",palabras:["cigarra","presa","vuelo","\xE1rbol","carne"]},en:{titulo:"The cicada",subtitulo:"Large prey that flies and lands",resumen:`Brown and big: the dragonfly of the prey. It lives airborne like the bee, but without pollinating and without biting \u2014 it only flies and settles on the trees. It is the largest of the prey and leaves ${e("cigarra")} of meat once it finally comes down.`,bloques:[{titulo:"What it is",texto:"FLYING PREY: it attacks no one and never touches your crumbs. It spends far more time perched than flying (fourteen turns landed to every six aloft), and in the air nobody can bite it. It drops in few bites once on the ground: its life is short for its bulk."},{titulo:"Hunting it",texto:"By waiting for it to land. Chasing it in the air does nothing, as with the bee or the wasp; but it stays grounded so long that a pack near where it settles is enough. Killed, it pays well: high meat for low life."},{titulo:"Where it turns up",texto:"Only where the location lists it (0026 \xA74.3): Mediterranean, dehesa, savanna, monsoon, outback, Caribbean, Amazon, prairie. Diurnal and toothless: with seasons on it falls in the harmless shift and withdraws at nightfall leaving no carcass."}],consejo:"It is the prize among prey: much meat for little life. Do not run after it; keep the pack where it tends to land and take it on the ground.",palabras:["cicada","prey","flight","tree","meat"]}},[r("Presa voladora","Flying prey"),n("cigarra"),s("cigarra"),i("cigarra"),{etiqueta:c("Vuelo","Flight"),valor:u("6 turnos volando \xB7 14 posada","6 turns aloft \xB7 14 landed")},{etiqueta:c("D\xF3nde sale","Where it spawns"),valor:u("Solo en ciertos sitios (0026)","Only at certain locations (0026)")}],["fauna/abeja","fauna/libelula","mundo/fauna"]),o("escolopendra","bicho",{es:{titulo:"La escolopendra",subtitulo:"La noche del tr\xF3pico h\xFAmedo",resumen:`Roja teja y larga: la amenaza nocturna del calor h\xFAmedo. Es la ara\xF1a de la noche de siempre, pero con un cuerpo alargado y m\xE1s vida \u2014 ${t.escolopendra.vida} mordiscos\u2014 y va a una casilla por turno, lo bastante r\xE1pida de noche para elegir a su v\xEDctima. Deja ${e("escolopendra")} de carne.`,bloques:[{titulo:"Qu\xE9 es",texto:"INSECT\xCDVORA NOCTURNA: no brota de d\xEDa. La trae el evento de la noche en el tr\xF3pico h\xFAmedo \u2014amazonas, caribe, monz\xF3n\u2014 y persigue desde ocho casillas, m\xE1s lejos que ninguna otra amenaza de la noche. Al amanecer se retira sin dejar carcasa."},{titulo:"C\xF3mo se pelea",texto:`Su presupuesto es una hormiga, como el de toda la noche: se lleva a una y se va. Va r\xE1pida (una casilla por turno) y persigue de lejos, as\xED que de noche, con la colonia entumecida, es dif\xEDcil quitarle la presa. Aguanta ${t.escolopendra.vida} mordiscos: matarla es cosa de una manada despierta.`},{titulo:"D\xF3nde sale",texto:"Solo de noche y solo en los tres sitios de calor h\xFAmedo que la listan (0026 \xA74.3): amazonas, caribe y monz\xF3n, junto a las ara\xF1as de siempre. En el caribe ocupa el puesto que hac\xEDa de errante hasta que la escolopendra existi\xF3 de verdad."}],consejo:"Es la peor noche del tr\xF3pico: r\xE1pida y de largo alcance. Recoge dentro cuanto puedas antes de que caiga la luz y no cuentes con arrancarle la presa una vez la tiene.",palabras:["escolopendra","nocturna","tr\xF3pico","h\xFAmedo","amenaza"]},en:{titulo:"The centipede",subtitulo:"The night of the humid tropics",resumen:`Tile-red and long: the nocturnal threat of humid heat. It is the ordinary night spider, but with an elongated body and more life, and it moves one tile a turn, fast enough after dark to pick its victim. It leaves ${e("escolopendra")} of meat.`,bloques:[{titulo:"What it is",texto:"NOCTURNAL INSECTIVORE: it never spawns by day. The night event brings it in the humid tropics \u2014 Amazon, Caribbean, monsoon \u2014 and it chases from eight tiles, further than any other night threat. It withdraws at dawn leaving no carcass."},{titulo:"Fighting it",texto:"Its budget is one ant, like all of the night: it takes one and leaves. It is fast (one tile a turn) and chases from afar, so after dark, with the colony torpid, it is hard to take its prey back. It is tough: killing it is a job for a wide-awake pack."},{titulo:"Where it turns up",texto:"Only at night and only in the three humid-heat locations that list it (0026 \xA74.3): Amazon, Caribbean and monsoon, alongside the usual spiders. In the Caribbean it fills the role the wandering spider stood in for until the centipede actually existed."}],consejo:"It is the worst night in the tropics: fast and long-ranged. Bring in all you can before the light goes, and do not count on wrenching its prey back once it has one.",palabras:["centipede","nocturnal","tropics","humid","threat"]}},[r("Insect\xEDvora nocturna","Nocturnal insectivore"),n("escolopendra"),s("escolopendra"),i("escolopendra"),h("escolopendra"),d("Una hormiga por noche","One ant per night")],["fauna/arana","fauna/escorpion","mundo/fauna"]),o("marabunta","bicho",{es:{titulo:"La legionaria",subtitulo:"La pieza del frente, de una en una",resumen:`Roja y menuda: la \xFAnica fauna del cat\xE1logo con cuerpo de hormiga. Sola no es nada \u2014seis mordiscos y ${e("marabunta")} de comida\u2014, pero nunca viene sola. Llegan catorce a la vez, formadas en l\xEDnea, y no se desv\xEDan por nada.`,bloques:[{titulo:"Qu\xE9 es",texto:`Un ENJAMBRE, no un insecto suelto, y por eso es la \xFAnica pieza que ocupa lo mismo que una hormiga: a ella se la muerde desde la casilla de al lado, mientras que a todas las dem\xE1s, con el cuerpo m\xE1s ancho, hay que morderlas desde dos. Muerde cada tres turnos, aguanta seis mordiscos y deja ${e("marabunta")} de comida, as\xED que despiezarla son ${m("marabunta")} bocados y se acab\xF3.`},{titulo:"En qu\xE9 se diferencia",texto:"En que no juega con las reglas del resto de los bichos. No duerme de noche, no necesita que nadie la est\xE9 mirando para avanzar \u2014los dem\xE1s se quedan quietos si no hay una hormiga que los vea\u2014 y no persigue a nadie: sigue su rumbo y muerde lo que le queda al paso. Mientras el frente cruza el mapa, no brota ning\xFAn otro bicho."},{titulo:"C\xF3mo se la pelea",texto:"A ella se le defiende todo el mundo por estar al lado, como a todo lo que muerde. Pero la orden de CAZAR no la toma como objetivo: contra el frente se ATACA o se aguanta. Cu\xE1ntas vienen lo decide el nivel de amenazas de la partida: catorce de serie, veintid\xF3s y treinta en los dos niveles altos."}],consejo:`No la cuentes como comida: ${e("marabunta")} por pieza es ruido. Lo que decide la marabunta es apartar del corredor lo que est\xE9 en su camino, y eso se hace con el aviso en la mano, no cuando ya la tienes encima.`,palabras:["marabunta","legionaria","frente","enjambre","evento"]},en:{titulo:"The army ant",subtitulo:"The front, one piece at a time",resumen:`Red and small: the only wildlife in the catalogue with an ant-sized body. On its own it is nothing \u2014 six bites and ${e("marabunta")} of food \u2014 but it never comes on its own. Fourteen arrive at once, formed in a line, and nothing makes them swerve.`,bloques:[{titulo:"What it is",texto:`A SWARM, not a loose insect, which is why it is the only creature that takes up exactly as much room as an ant: you bite it from the neighbouring tile, whereas everything else, with its wider body, has to be bitten from two. It bites every three turns, takes six bites and leaves ${e("marabunta")} of food, so butchering it is ${m("marabunta")} mouthfuls and done.`},{titulo:"How it differs",texto:"It does not play by the rules the other creatures follow. It does not sleep at night, it does not need anyone watching for it to move \u2014 the rest freeze when no ant can see them \u2014 and it chases nobody: it holds its heading and bites whatever is left in the way. While the front is crossing the map, no other creature spawns at all."},{titulo:"Fighting it",texto:"Everyone fights it just by standing beside it, as with anything that bites. But the HUNT order does not target it: against the front you ATTACK or you hold. How many come is set by the match threat level: fourteen as standard, twenty-two and thirty on the two high settings."}],consejo:`Do not count it as food: ${e("marabunta")} apiece is noise. What decides an army-ant crossing is clearing the corridor of whatever stands in it, and that is done with the warning in hand, not once they are on top of you.`,palabras:["army ant","marabunta","front","swarm","event"]}},[r("Enjambre","Swarm"),n("marabunta"),s("marabunta"),i("marabunta"),{etiqueta:c("El frente","The front"),valor:u(`${g.marabunta.n} piezas de serie`,`${g.marabunta.n} pieces by default`)},d("No se caza: se aguanta","Not hunted: endured")],["mundo/marabunta","mundo/fauna","hormiguero/defensa"])];export{z as TARJETAS_FAUNA};
